        if (c.cmd.silenceTailSec == null) c.cmd.silenceTailSec = 10;
        if (c.cmd.ajusteMs == null) c.cmd.ajusteMs = 0;
        if (c.cmd.trainGapMs == null) c.cmd.trainGapMs = 150;
